#include <chrono>
#include <cstdio>
#include <vector>

double suma_cuatro(const std::vector<double>& v) {
    double a = 0.0, b = 0.0, c = 0.0, d = 0.0;
    const std::size_t n = v.size();
    std::size_t i = 0;
    for (; i + 4 <= n; i += 4) {
        a += v[i];
        b += v[i + 1];
        c += v[i + 2];
        d += v[i + 3];
    }
    for (; i < n; ++i) a += v[i];  // resto cuando n no es múltiplo de 4
    return a + b + c + d;
}

int main() {
    std::vector<double> v(50'000'000, 1.0);
    const auto t0 = std::chrono::steady_clock::now();
    const double s = suma_cuatro(v);
    const auto t1 = std::chrono::steady_clock::now();

    const double ms = std::chrono::duration<double, std::milli>(t1 - t0).count();
    std::printf("%.0f en %.1f ms\n", s, ms);
    return 0;
}

#include <chrono>
#include <cstdio>
#include <thread>

struct Juntos {
    volatile long long a = 0;
    volatile long long b = 0;  // misma linea de caché que a
};

struct Separados {
    alignas(64) volatile long long a = 0;
    alignas(64) volatile long long b = 0;  // cada uno en su linea
};

constexpr long long N = 50'000'000;

template <typename T>
double medir(T& c) {
    const auto t0 = std::chrono::steady_clock::now();
    std::thread h1([&] { for (long long i = 0; i < N; ++i) c.a = c.a + 1; });
    std::thread h2([&] { for (long long i = 0; i < N; ++i) c.b = c.b + 1; });
    h1.join();
    h2.join();
    return std::chrono::duration<double, std::milli>(std::chrono::steady_clock::now() - t0).count();
}

int main() {
    Juntos juntos;
    Separados separados;
    std::printf("misma linea   %.1f ms\n", medir(juntos));
    std::printf("lineas aparte %.1f ms\n", medir(separados));
    std::printf("%lld %lld\n", juntos.a, separados.a);
    return 0;
}

