#include <chrono>
#include <cmath>
#include <cstdio>

int main() {
    constexpr long long n = 50'000'000;

    auto t0 = std::chrono::steady_clock::now();
    double secuencial = 0.0;
    for (long long i = 0; i < n; ++i) secuencial += static_cast<double>(i) * i;
    auto t1 = std::chrono::steady_clock::now();

    double paralela = 0.0;
#pragma omp parallel for reduction(+ : paralela) schedule(static)
    for (long long i = 0; i < n; ++i) paralela += static_cast<double>(i) * i;
    auto t2 = std::chrono::steady_clock::now();

    auto ms = [](auto a, auto b) {
        return std::chrono::duration<double, std::milli>(b - a).count();
    };
    std::printf("secuencial %.1f ms  %.0f\n", ms(t0, t1), secuencial);
    std::printf("paralela   %.1f ms  %.0f\n", ms(t1, t2), paralela);
    std::printf("iguales: %s\n", std::fabs(secuencial - paralela) < 1e-6 ? "si" : "no");
    return 0;
}

#include <chrono>
#include <cstdio>
#include <thread>

struct Juntos {
    volatile long long a = 0;
    volatile long long b = 0;  // comparten linea de cache
};

struct Separados {
    alignas(64) volatile long long a = 0;
    alignas(64) volatile long long b = 0;
};

constexpr long long N = 50'000'000;

template <typename T>
double medir(T& c) {
    const auto t0 = std::chrono::steady_clock::now();
    std::thread h1([&] { for (long long i = 0; i < N; ++i) c.a = c.a + 1; });
    std::thread h2([&] { for (long long i = 0; i < N; ++i) c.b = c.b + 1; });
    h1.join();
    h2.join();
    return std::chrono::duration<double, std::milli>(std::chrono::steady_clock::now() - t0).count();
}

int main() {
    Juntos juntos;
    Separados separados;
    std::printf("juntos   %6.1f ms\n", medir(juntos));
    std::printf("separados %6.1f ms\n", medir(separados));
    std::printf("%lld %lld\n", juntos.a, separados.a);
    return 0;
}

